    fputc(0x00, f);  /* Byte 0 */
    fputc(0x00, f);  /* Byte 1 */
    fputc(0x7E, f);  /* Byte 2: bits 23-16 = 126 */
    fputc(0x00, f);  /* Byte 3 */

